{
  "phase": "start",
  "taint_analysis": {
    "function": "TA_InvokeCommandEntryPoint",
    "tainted_vars": ["params[0..3]", "tainted_size_var"],
    "propagation": [
      {"lhs": "dst", "rhs": "params[0].memref.buffer", "site": "file.c:42"}
    ],
    "sanitizers": [
      {"kind": "bounds_check", "site": "file.c:45", "evidence": "if (size > MAX_BUF)"}
    ],
    "taint_blocked": false
  },
  "vulnerability_candidates": [
    {
      "file": "file.c",
      "line": 42,
      "function": "TA_InvokeCommandEntryPoint",
      "rule_id": "Input Validation Weakness",
      "why": "tainted memref.size reaches a memory operation without visible bounds validation",
      "sink_function": "="
    }
  ]
}

Output exactly one JSON. No prose. No code fences.

